import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;
import java.util.zip.CRC32C;
import java.util.zip.GZIPOutputStream;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalSearchBoundedMemoryTest {

	@TempDir
	Path directory;

	@Test
	void searchRejectsCorruptFramesLargerThanHeap() throws Exception {
		String classpath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		Path output = directory.resolve("search-memory.log");
		Process process = new ProcessBuilder(java, "-Xmx32m", "-XX:+ExitOnOutOfMemoryError", "-cp", classpath,
				ValueStoreWalSearchBoundedMemoryTest.class.getName(), directory.toString())
						.redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		boolean exited;
		try {
			exited = process.waitFor(60, TimeUnit.SECONDS);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
				process.waitFor(10, TimeUnit.SECONDS);
			}
		}
		String log = Files.readString(output);
		assertThat(exited).withFailMessage("Search memory probe timed out:%n%s", log).isTrue();
		assertThat(process.exitValue()).withFailMessage("Search memory probe failed:%n%s", log).isZero();
		assertThat(log).contains("SEARCH_MEMORY_PROBE_PASSED");
	}

	@Test
	void findsInterleavedBootstrapRecordOutsideFilenameCandidate() throws Exception {
		writeSegment(directory.resolve("wal-5.v1"), 1, 5,
				mint(1, 5, "five"), mint(2, 1, "one"));
		writeSegment(directory.resolve("wal-3.v1"), 2, 3, mint(3, 3, "three"));
		ValueStoreWalSearch search = ValueStoreWalSearch.open(config(directory));
		assertThat(search.findValueById(1)).isNotNull().hasToString("_:one");
	}

	@Test
	void findsValuesWhenSegmentCountExceedsCacheLimit() throws Exception {
		for (int id = 1; id <= 1_030; id++) {
			writeSegment(directory.resolve("wal-" + id + ".v1"), id, id, mint(id, id, "node-" + id));
		}
		ValueStoreWalSearch search = ValueStoreWalSearch.open(config(directory));
		assertThat(search.findValueById(1_029)).isNotNull().hasToString("_:node-1029");
		writeSegment(directory.resolve("wal-1031.v1"), 1_031, 1_031, mint(1_031, 1_031, "node-1031"));
		assertThat(search.findValueById(1_031)).isNotNull().hasToString("_:node-1031");
	}

	@Test
	void limitsNestedTripleReconstruction() throws Exception {
		try (OutputStream output = new BufferedOutputStream(Files.newOutputStream(directory.resolve("wal-1.v1")))) {
			writeFrame(output, header(1, 1));
			writeFrame(output, "{\"t\":\"M\",\"lsn\":1,\"id\":1,\"vk\":\"I\",\"lex\":\"http://example.org/p\"}\n");
			writeFrame(output, mint(2, 2, "leaf"));
			for (int id = 3; id <= 70; id++) {
				writeFrame(output, "{\"t\":\"M\",\"lsn\":" + id + ",\"id\":" + id
						+ ",\"vk\":\"T\",\"lex\":\"" + (id - 1) + " 1 2\"}\n");
			}
		}
		ValueStoreWalSearch search = ValueStoreWalSearch.open(config(directory));
		assertThatThrownBy(() -> search.findValueById(70)).isInstanceOf(IOException.class)
				.hasMessageContaining("nesting");
	}

	public static void main(String[] args) throws Exception {
		Path root = Path.of(args[0]);
		for (boolean compressed : new boolean[] { false, true }) {
			Path walDirectory = Files.createDirectories(root.resolve(compressed ? "compressed" : "uncompressed"));
			Path segment = walDirectory.resolve(compressed ? "wal-1.v1.gz" : "wal-1.v1");
			try (OutputStream file = new BufferedOutputStream(Files.newOutputStream(segment));
					OutputStream output = compressed ? new GZIPOutputStream(file) : file) {
				writeFrame(output, header(1, 1));
				int length = 64 * 1024 * 1024;
				writeIntLE(output, length);
				if (compressed) {
					byte[] zeros = new byte[8192];
					for (int written = 0; written < length; written += zeros.length) {
						output.write(zeros);
					}
					writeIntLE(output, 0);
				}
			}
			if (ValueStoreWalSearch.open(config(walDirectory)).findValueById(1) != null) {
				throw new AssertionError("Search must not recover a value from a corrupt frame");
			}
		}
		System.out.println("SEARCH_MEMORY_PROBE_PASSED");
	}

	private static ValueStoreWalConfig config(Path directory) {
		return ValueStoreWalConfig.builder().walDirectory(directory).storeUuid("search-memory-test").build();
	}

	private static String header(int sequence, int firstId) {
		return "{\"t\":\"V\",\"ver\":1,\"store\":\"search-memory-test\",\"engine\":\"valuestore\","
				+ "\"created\":0,\"segment\":" + sequence + ",\"firstId\":" + firstId + "}\n";
	}

	private static String mint(long lsn, int id, String lexical) {
		return "{\"t\":\"M\",\"lsn\":" + lsn + ",\"id\":" + id
				+ ",\"vk\":\"B\",\"lex\":\"" + lexical + "\",\"dt\":\"\",\"lang\":\"\",\"hash\":0}\n";
	}

	private static void writeSegment(Path path, int sequence, int firstId, String... records) throws IOException {
		try (OutputStream output = new BufferedOutputStream(Files.newOutputStream(path))) {
			writeFrame(output, header(sequence, firstId));
			for (String record : records) {
				writeFrame(output, record);
			}
		}
	}

	private static void writeFrame(OutputStream output, String json) throws IOException {
		byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
		CRC32C crc = new CRC32C();
		crc.update(bytes, 0, bytes.length);
		writeIntLE(output, bytes.length);
		output.write(bytes);
		writeIntLE(output, (int) crc.getValue());
	}

	private static void writeIntLE(OutputStream output, int value) throws IOException {
		output.write(value);
		output.write(value >>> 8);
		output.write(value >>> 16);
		output.write(value >>> 24);
	}
}
